#!/usr/bin/env bash
set -euo pipefail
mkdir -p src/main/resources/META-INF src/main/resources/assets/aphernix/lang src/main/resources/assets/aphernix/models/item src/main/resources/assets/aphernix/textures/entity src/main/resources/data/aphernix/forge/biome_modifier src/main/resources/data/aphernix/loot_tables/entities
cat > src/main/resources/META-INF/mods.toml <<'EOF'
modLoader="javafml"
loaderVersion="${loader_version_range}"
license="${mod_license}"
[[mods]]
modId="${mod_id}"
version="${mod_version}"
displayName="${mod_name}"
logoFile="aphernix_icon.png"
authors="${mod_authors}"
description='''${mod_description}'''
[[dependencies.${mod_id}]]
modId="forge"
mandatory=true
versionRange="${forge_version_range}"
ordering="NONE"
side="BOTH"
[[dependencies.${mod_id}]]
modId="minecraft"
mandatory=true
versionRange="${minecraft_version_range}"
ordering="NONE"
side="BOTH"
EOF
cat > src/main/resources/pack.mcmeta <<'EOF'
{"pack":{"description":"${mod_name} resources","pack_format":15}}
EOF
cat > src/main/resources/assets/aphernix/lang/en_us.json <<'EOF'
{"entity.aphernix.aphernix":"Aphernix","item.aphernix.aphernix_spawn_egg":"Aphernix Spawn Egg"}
EOF
cat > src/main/resources/assets/aphernix/lang/tr_tr.json <<'EOF'
{"entity.aphernix.aphernix":"Aphernix","item.aphernix.aphernix_spawn_egg":"Aphernix Çağırma Yumurtası"}
EOF
cat > src/main/resources/assets/aphernix/models/item/aphernix_spawn_egg.json <<'EOF'
{"parent":"item/template_spawn_egg"}
EOF
cat > src/main/resources/data/aphernix/forge/biome_modifier/add_aphernix_spawns.json <<'EOF'
{"type":"forge:add_spawns","biomes":"#minecraft:is_overworld","spawners":{"type":"aphernix:aphernix","weight":4,"minCount":1,"maxCount":1}}
EOF
cat > src/main/resources/data/aphernix/loot_tables/entities/aphernix.json <<'EOF'
{"type":"minecraft:entity","pools":[]}
EOF
base64 -d > src/main/resources/assets/aphernix/textures/entity/aphernix.png <<'EOF'

EOF
cp src/main/resources/assets/aphernix/textures/entity/aphernix.png src/main/resources/aphernix_icon.png
